/**
 * Writes src/icons.generated.ts: the @xos/icons registry (registry/<owner>.txt plus the canon glyph
 * map) imported from lucide-react-native, so Compass bundles only the icons XOS draws by name, the
 * same set as the web. Names match lucide-react one for one at the shared 1.53.0 pin.
 *
 * Usage: node scripts/generate-icons.mjs [--check]
 * With --check, writes nothing and exits 1 when the generated file is out of date.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as prettier from "prettier";

const here = dirname(fileURLToPath(import.meta.url));
const target = join(here, "../src/icons.generated.ts");
const registry = readFileSync(
  join(here, "../node_modules/@xos/icons/src/registry.generated.ts"),
  "utf8",
);
const match = /registeredIconNames = (\[[^\]]*\]) as const/.exec(registry);
if (!match) {
  console.error("Cannot read registeredIconNames from @xos/icons/src/registry.generated.ts");
  process.exit(1);
}
const names = [...match[1].matchAll(/"([A-Za-z0-9]+)"/g)].map((m) => m[1]);

const source = `/* Generated by scripts/generate-icons.mjs from the @xos/icons registry. Do not edit; run \`pnpm --filter @xos/ui-native generate:icons\`. */
import type { LucideIcon } from "lucide-react-native";
import { ${names.map((n) => `${n} as Lucide${n}`).join(", ")} } from "lucide-react-native";

/** The lucide-react-native component for each registered icon name. */
export const nativeIconRegistry: Readonly<Record<string, LucideIcon>> = Object.freeze({ ${names
  .map((n) => `${n}: Lucide${n}`)
  .join(", ")} });
`;

const config = (await prettier.resolveConfig(target)) ?? {};
const output = await prettier.format(source, { ...config, filepath: target });

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch (error) {
    console.error(`Cannot read ${target}: ${String(error)}`);
    process.exit(1);
  }
  if (current !== output) {
    console.error(
      "src/icons.generated.ts is out of date. Run pnpm --filter @xos/ui-native generate:icons.",
    );
    process.exit(1);
  }
} else {
  writeFileSync(target, output);
}
